// Auto-generated: SVG icons embedded as data URLs
var ICON_DATA = {
  potions: {
    'healing_brew': 'data:image/svg+xml;base64,',
    'greater_heal': 'data:image/svg+xml;base64,',
    'strength_elixir': 'data:image/svg+xml;base64,',
    'iron_skin': 'data:image/svg+xml;base64,',
    'swift_potion': 'data:image/svg+xml;base64,',
    'regen_potion': 'data:image/svg+xml;base64,',
    'phoenix_draught': 'data:image/svg+xml;base64,',
    'venom_blade': 'data:image/svg+xml;base64,',
  },
  status: {
    'poison': 'data:image/svg+xml;base64,',
    'paralyze': 'data:image/svg+xml;base64,',
    'sleep': 'data:image/svg+xml;base64,',
    'freeze': 'data:image/svg+xml;base64,',
    'burn': 'data:image/svg+xml;base64,',
    'dizzy': 'data:image/svg+xml;base64,',
  },
  ui: {
    'settings': 'data:image/svg+xml;base64,',
    'bestiary': 'data:image/svg+xml;base64,',
    'exit': 'data:image/svg+xml;base64,',
    'minimap': 'data:image/svg+xml;base64,',
  }
};

// Load all icons from embedded data URLs synchronously
function loadGameIcons(){
  return new Promise(function(resolve){
    var categories = ['potions','status','ui'];
    var pending = 0, done = 0;
    function tryResolve(){ if(done>=pending) resolve(); }
    categories.forEach(function(cat){
      var map = ICON_DATA[cat];
      if(!map) return;
      Object.keys(map).forEach(function(key){
        pending++;
        var img = new Image();
        img.onload = function(){ ICONS[cat][key]=img; done++; tryResolve(); };
        img.onerror = function(){ done++; tryResolve(); };
        img.src = map[key];
      });
    });
    if(pending===0) resolve();
  });
}
